#!/usr/bin/env bash
# Qualification driver for the C1 offline installation ceremony (issue #1225).
#
# Proves the complete prepare -> offline-sign -> install -> startup journey of
# a C1-bearing release bundle on a clean, disposable Ubuntu 24.04 KVM guest,
# including fail-closed negative tests for missing and tampered policy, state,
# and trust material. All key material is throwaway qualification data
# generated by sign.py; nothing here touches production custody.
#
# Usage:
#   run-guest-ceremony.sh --bundle DIR --keys DIR --evidence DIR \
#       [--image PATH] [--keep-guest]
#
# --bundle is an extracted C1-bearing release bundle (contains manifest.json,
# bin/, packaging/); --keys is a sign.py keygen directory whose policy key id
# and public key were baked into the bundle manifest. The guest is created
# with a fixed name prefix and destroyed again unless --keep-guest is given.
set -Eeuo pipefail

BUNDLE=
KEYS=
EVIDENCE=
ARTIFACT_SHA256=
IMAGE="${O3K_C1QUAL_IMAGE:-/var/tmp/pp6-e4-inputs/ubuntu-24.04-server-cloudimg-amd64.img}"
IMAGE_SHA256="${O3K_C1QUAL_IMAGE_SHA256:-}"
KEEP_GUEST=0
VM_NAME="o3k-c1qual-$$"
SSH_USER=o3kqual
while (($#)); do
  case "$1" in
    --bundle) BUNDLE="$2"; shift 2;;
    --keys) KEYS="$2"; shift 2;;
    --evidence) EVIDENCE="$2"; shift 2;;
    --artifact-sha256) ARTIFACT_SHA256="$2"; shift 2;;
    --image) IMAGE="$2"; shift 2;;
    --image-sha256) IMAGE_SHA256="$2"; shift 2;;
    --keep-guest) KEEP_GUEST=1; shift;;
    *) echo "unknown option: $1" >&2; exit 2;;
  esac
done
[[ -n "$BUNDLE" && -n "$KEYS" && -n "$EVIDENCE" && -n "$ARTIFACT_SHA256" ]] || {
  echo "usage: $0 --bundle DIR --keys DIR --evidence DIR --artifact-sha256 HEX [--image PATH] [--keep-guest]" >&2
  exit 2
}
[[ "$ARTIFACT_SHA256" =~ ^[0-9a-f]{64}$ ]] \
  || { echo "--artifact-sha256 must be the verified 64-hex tarball digest" >&2; exit 2; }
[[ -f "$BUNDLE/manifest.json" && -x "$BUNDLE/bin/o3kd" && -x "$BUNDLE/bin/o3k-compute" ]] \
  || { echo "--bundle must be an extracted libvirt release bundle" >&2; exit 2; }
python3 - "$BUNDLE/manifest.json" <<'PY'
import json, sys
m = json.load(open(sys.argv[1], encoding="utf-8"))
assert "installation_policy_authority" in m, "bundle is not C1-bearing"
PY
[[ -f "$KEYS/keys.json" ]] || { echo "--keys must be a sign.py keygen directory" >&2; exit 2; }
[[ -f "$IMAGE" ]] || { echo "guest base image missing: $IMAGE" >&2; exit 2; }
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
mkdir -p "$EVIDENCE"
WORK="$EVIDENCE/work"
mkdir -p "$WORK"

if virsh dominfo "$VM_NAME" >/dev/null 2>&1; then
  echo "refusing to reuse existing guest $VM_NAME" >&2
  exit 1
fi

cleanup() {
  local rc=$?
  if [[ "$KEEP_GUEST" != 1 ]]; then
    virsh destroy "$VM_NAME" >/dev/null 2>&1 || true
    virsh undefine "$VM_NAME" --remove-all-storage >/dev/null 2>&1 || true
    rm -rf -- "$WORK/overlay.qcow2" "$WORK/seed.iso"
  fi
  exit "$rc"
}
trap cleanup EXIT

log() { printf '%s %s\n' "$(date -u +%H:%M:%S)" "$*" | tee -a "$EVIDENCE/driver.log"; }

# ---- base image authentication ------------------------------------------
if [[ -n "$IMAGE_SHA256" ]]; then
  echo "$IMAGE_SHA256  $IMAGE" | sha256sum -c - >>"$EVIDENCE/driver.log"
fi
sha256sum "$IMAGE" >"$EVIDENCE/base-image.sha256"

# ---- disposable guest -----------------------------------------------------
log "creating disposable guest $VM_NAME"
qemu-img create -f qcow2 -b "$IMAGE" -F qcow2 "$WORK/overlay.qcow2" 24G >>"$EVIDENCE/driver.log"
ssh-keygen -t ed25519 -N "" -C "o3k-c1qual-run" -f "$WORK/id_ed25519" -q
cat >"$WORK/user-data" <<EOF
#cloud-config
hostname: $VM_NAME
users:
  - name: $SSH_USER
    sudo: ALL=(ALL) NOPASSWD:ALL
    shell: /bin/bash
    ssh_authorized_keys:
      - $(cat "$WORK/id_ed25519.pub")
ssh_pwauth: false
EOF
cat >"$WORK/meta-data" <<EOF
instance-id: $VM_NAME
local-hostname: $VM_NAME
EOF
genisoimage -quiet -output "$WORK/seed.iso" -volid cidata -joliet -rock "$WORK/user-data" "$WORK/meta-data"
virt-install --name "$VM_NAME" --memory 8192 --vcpus 4 --cpu host-passthrough \
  --disk "path=$WORK/overlay.qcow2,format=qcow2,bus=virtio" \
  --disk "path=$WORK/seed.iso,device=cdrom" \
  --os-variant ubuntu24.04 --network network=default,model=virtio \
  --graphics none --console pty,target_type=serial --noautoconsole --import \
  >>"$EVIDENCE/driver.log" 2>&1

GUEST_IP=
for _ in $(seq 1 60); do
  GUEST_IP="$(virsh domifaddr "$VM_NAME" --source lease 2>/dev/null | awk '/ipv4/{split($4,a,"/"); print a[1]; exit}')"
  [[ -n "$GUEST_IP" ]] && break
  sleep 5
done
[[ -n "$GUEST_IP" ]] || { echo "guest did not obtain an address" >&2; exit 1; }
log "guest $VM_NAME at $GUEST_IP"

SSH=(ssh -i "$WORK/id_ed25519" -o StrictHostKeyChecking=no -o "UserKnownHostsFile=$WORK/known_hosts"
     -o ConnectTimeout=10 -o LogLevel=ERROR "$SSH_USER@$GUEST_IP")
SCP=(scp -i "$WORK/id_ed25519" -o StrictHostKeyChecking=no -o "UserKnownHostsFile=$WORK/known_hosts"
     -o LogLevel=ERROR)
for _ in $(seq 1 60); do
  "${SSH[@]}" true 2>/dev/null && break
  sleep 5
done
"${SSH[@]}" true || { echo "guest ssh did not come up" >&2; exit 1; }

log "installing guest prerequisites (libvirt/qemu)"
"${SSH[@]}" 'sudo apt-get update -qq && sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq libvirt-daemon-system libvirt-clients qemu-kvm jq curl openssl' \
  >"$EVIDENCE/guest-apt.log" 2>&1

log "staging bundle and running TLS bootstrap"
"${SSH[@]}" 'rm -rf /tmp/o3k-bundle && mkdir -p /tmp/o3k-bundle'
tar -C "$BUNDLE" -cf - . | "${SSH[@]}" 'tar -C /tmp/o3k-bundle -xf -'
"${SSH[@]}" 'sudo /tmp/o3k-bundle/packaging/bootstrap-certs.sh' >"$EVIDENCE/guest-tls-bootstrap.log" 2>&1

INSTALL=(sudo /tmp/o3k-bundle/packaging/install.sh --profile libvirt --noninteractive
         --prefix /usr/local --data-dir /var/lib/o3k --config-dir /etc/o3k --log-dir /var/log/o3k
         --release-artifact-sha256 "$ARTIFACT_SHA256")

# ---- negative: a C1 release refuses a ceremony-less install ---------------
log "negative: install without C1 inputs must fail closed with the journey message"
if "${SSH[@]}" "${INSTALL[*]}" >"$EVIDENCE/negative-no-c1-inputs.log" 2>&1; then
  echo "install without C1 inputs unexpectedly succeeded" >&2
  exit 1
fi
grep -Fq 'C1 release requires offline-signed policy/state/trust inputs' "$EVIDENCE/negative-no-c1-inputs.log" \
  || { echo "missing C1 journey message in the refused install output" >&2; exit 1; }
# The negative ran before prepare, so the journey must have stopped before any
# systemd enablement.
if "${SSH[@]}" 'systemctl is-enabled o3kd.service 2>/dev/null' | grep -qx enabled; then
  echo "o3kd was enabled despite the refused C1-less install" >&2
  exit 1
fi

# ---- step 1: prepare -------------------------------------------------------
log "prepare: --c1-prepare-only"
"${SSH[@]}" "${INSTALL[*]} --c1-prepare-only --c1-backend sqlite" \
  >"$EVIDENCE/prepare.log" 2>&1
grep -o '{"format":"o3k-recovery-provisioning-v1".*}' "$EVIDENCE/prepare.log" \
  | tail -n1 >"$WORK/descriptor.json"
python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); assert d["unsigned"] is True and d["authentication"]=="none"' \
  "$WORK/descriptor.json"
cp "$WORK/descriptor.json" "$EVIDENCE/descriptor.json"

# ---- step 2: offline signing (host side, throwaway keys) -------------------
log "signing descriptor with qualification keys"
python3 "$SCRIPT_DIR/sign.py" sign --descriptor "$WORK/descriptor.json" \
  --keys "$KEYS" --out "$WORK/signed" | tee "$EVIDENCE/sign.json"

tamper() { # tamper <file> <out>: flip one byte in the middle
  python3 - "$1" "$2" <<'PY'
import sys
data = bytearray(open(sys.argv[1], "rb").read())
data[len(data) // 2] ^= 0x01
open(sys.argv[2], "wb").write(bytes(data))
PY
}
mkdir -p "$WORK/tampered"
for doc in policy state trust; do
  tamper "$WORK/signed/$doc.json" "$WORK/tampered/$doc.json"
done

stage_docs() { # stage_docs <dir>: copy doc set into the guest as root-owned inputs
  local staged  # bash loop variables are global by default; never clobber the caller
  "${SSH[@]}" 'sudo rm -rf /var/lib/o3k-c1-inputs && sudo mkdir -m 0700 /var/lib/o3k-c1-inputs'
  for staged in policy state trust; do
    "${SCP[@]}" -q "$1/$staged.json" "$SSH_USER@$GUEST_IP:/tmp/$staged.json"
    "${SSH[@]}" "sudo install -o root -g root -m 0600 /tmp/$staged.json /var/lib/o3k-c1-inputs/$staged.json && rm -f /tmp/$staged.json"
  done
}

run_install_with_docs() { # run_install_with_docs <logfile>; returns install rc
  local logfile="$1"
  set +e
  "${SSH[@]}" "${INSTALL[*]} --c1-policy /var/lib/o3k-c1-inputs/policy.json --c1-state /var/lib/o3k-c1-inputs/state.json --c1-trust /var/lib/o3k-c1-inputs/trust.json" \
    >"$logfile" 2>&1
  local rc=$?
  set -e
  return "$rc"
}

# ---- negatives: tampered documents must be rejected ------------------------
for doc in policy state trust; do
  log "negative: tampered $doc must be rejected"
  mkdir -p "$WORK/mix-$doc"
  for other in policy state trust; do
    if [[ "$other" == "$doc" ]]; then
      cp "$WORK/tampered/$doc.json" "$WORK/mix-$doc/$other.json"
    else
      cp "$WORK/signed/$other.json" "$WORK/mix-$doc/$other.json"
    fi
  done
  stage_docs "$WORK/mix-$doc"
  if run_install_with_docs "$EVIDENCE/negative-tampered-$doc.log"; then
    echo "tampered $doc was accepted" >&2
    exit 1
  fi
  # The negative only counts when the run reached and failed the C1
  # provisioning step, not when it failed earlier for an unrelated reason.
  grep -Fq 'installation provisioning failed' "$EVIDENCE/negative-tampered-$doc.log"     || { echo "tampered $doc negative did not reach provisioning verification" >&2; exit 1; }
  if "${SSH[@]}" 'systemctl is-active o3kd.service 2>/dev/null' | grep -qx active; then
    echo "o3kd became active under a tampered $doc" >&2
    exit 1
  fi
done

# ---- step 3: install with authentic documents ------------------------------
log "installing with authentic signed documents"
stage_docs "$WORK/signed"
run_install_with_docs "$EVIDENCE/install.log" \
  || { echo "authentic C1 install failed; see $EVIDENCE/install.log" >&2; exit 1; }

# wait_for_services <evidence-file>: poll o3kd/o3k-compute until both are
# active. is-active exits 3 for non-active units and ssh propagates that, so
# the probe never runs bare under set -e/pipefail. A unit in the failed state
# (e.g. systemd burst-limit exhaustion) never recovers by waiting: capture
# the journals and fail immediately instead.
wait_for_services() {
  local outfile="$1" state
  local i
  for i in $(seq 1 24); do
    state="$("${SSH[@]}" 'systemctl is-active o3kd.service; systemctl is-active o3k-compute.service; true')"
    if [[ "$(sed -n 1p <<<"$state")" == active \
      && "$(sed -n 2p <<<"$state")" == active ]]; then
      printf '%s\n' "$state" | tee "$outfile"
      return 0
    fi
    if [[ "$state" == *failed* ]]; then
      break
    fi
    sleep 5
  done
  printf '%s\n' "$state" | tee "$outfile"
  "${SSH[@]}" 'sudo journalctl -u o3kd.service -u o3k-compute.service --no-pager -n 80' \
    >"$EVIDENCE/service-failure-journal.txt" 2>&1 || true
  echo "services did not both become active; see service-failure-journal.txt" >&2
  exit 1
}

log "asserting healthy services"
# o3k-compute can still be converging right after enablement; wait fail-closed.
wait_for_services "$EVIDENCE/services-active.txt"
"${SSH[@]}" 'curl -fsS http://127.0.0.1:18080/healthz' | tee "$EVIDENCE/o3kd-healthz.json"
"${SSH[@]}" 'systemctl status o3kd.service --no-pager -l | head -30; echo ---; sudo journalctl -u o3kd.service -n 30 --no-pager' \
  >"$EVIDENCE/o3kd-status.txt" 2>&1

# ---- negatives: post-install tampering must deny startup -------------------
tamper_installed_file() { # <guest path>
  "${SSH[@]}" "sudo python3 - '$1'" <<'PY'
import sys
p = sys.argv[1]
d = bytearray(open(p, "rb").read())
d[len(d) // 2] ^= 1
open(p, "wb").write(bytes(d))
PY
}
assert_denied_after_tamper() { # <name>
  local name="$1"
  "${SSH[@]}" 'sudo systemctl stop o3kd.service o3k-compute.service'
  if "${SSH[@]}" 'sudo systemctl start o3kd.service' 2>/dev/null; then
    sleep 3
    if "${SSH[@]}" 'systemctl is-active o3kd.service' | grep -qx active; then
      echo "o3kd started despite $name" >&2
      exit 1
    fi
  fi
  "${SSH[@]}" 'sudo journalctl -u o3kd.service -n 10 --no-pager' >"$EVIDENCE/negative-post-$name.log" 2>&1 || true
  "${SSH[@]}" 'sudo systemctl reset-failed o3kd.service 2>/dev/null || true'
}
assert_recovers() { # <name>
  "${SSH[@]}" 'sudo systemctl start o3kd.service'
  "${SSH[@]}" 'systemctl is-active o3kd.service' | grep -qx active \
    || { echo "o3kd did not recover after restoring $1" >&2; exit 1; }
}

log "negative: tampered installed policy must deny startup"
"${SSH[@]}" 'sudo cp -a /etc/o3k/installation-policy.json /tmp/o3k-c1-policy.bak'
tamper_installed_file /etc/o3k/installation-policy.json
assert_denied_after_tamper tampered-policy
"${SSH[@]}" 'sudo cp -a /tmp/o3k-c1-policy.bak /etc/o3k/installation-policy.json && sudo rm -f /tmp/o3k-c1-policy.bak'
assert_recovers tampered-policy

log "negative: missing state high-water must deny startup"
"${SSH[@]}" 'sudo ls -la /var/lib/o3k-recovery-state /var/lib/o3k-recovery-state/*/' >"$EVIDENCE/recovery-state-layout.txt" 2>&1
"${SSH[@]}" "sudo bash -c 'set -e; d=\$(echo /var/lib/o3k-recovery-state/*/); cp -a \"\$d/state.json\" /tmp/o3k-c1-state.bak && rm -f \"\$d/state.json\"'"
assert_denied_after_tamper missing-state
"${SSH[@]}" "sudo bash -c 'set -e; d=\$(echo /var/lib/o3k-recovery-state/*/); cp -a /tmp/o3k-c1-state.bak \"\$d/state.json\" && rm -f /tmp/o3k-c1-state.bak'"
assert_recovers missing-state

log "negative: tampered installed trust bundle must deny startup"
"${SSH[@]}" 'sudo cp -a /etc/o3k/recovery-trust.json /tmp/o3k-c1-trust.bak'
tamper_installed_file /etc/o3k/recovery-trust.json
assert_denied_after_tamper tampered-trust
"${SSH[@]}" 'sudo cp -a /tmp/o3k-c1-trust.bak /etc/o3k/recovery-trust.json && sudo rm -f /tmp/o3k-c1-trust.bak'
assert_recovers tampered-trust

"${SSH[@]}" 'sudo systemctl start o3k-compute.service'
wait_for_services "$EVIDENCE/services-final.txt"

# ---- evidence --------------------------------------------------------------
"${SSH[@]}" 'sudo tar -C / -czf - etc/o3k/installation-policy.json etc/o3k/recovery-trust.json 2>/dev/null' \
  >"$EVIDENCE/installed-c1-documents.tar.gz"
{
  echo "guest: $VM_NAME ($GUEST_IP)"
  virsh dominfo "$VM_NAME" | sed -n '1,8p'
} >"$EVIDENCE/guest-identity.txt"
(cd "$EVIDENCE" && find . -type f ! -name SHA256SUMS -print0 | sort -z | xargs -0 sha256sum >SHA256SUMS)
log "ceremony journey complete: all positive and negative assertions passed"
